export function getPool(){throw Error('Test must supply injected mock database');}
export async function withTransaction(fn,{db}={}){
  const tx=await db.connect();
  await tx.query('BEGIN');
  try{ const result=await fn(tx);await tx.query('COMMIT');return result }
  catch(e){await tx.query('ROLLBACK');throw e}
  finally{tx.release()}
}

